function soql(value) { return String(value).replace(/\\/g,'\\\\').replace(/'/g,"\\'"); }
function checkCall(archive,body,hash) {
  const email=String(archive.attendee_email||'').trim().toLowerCase(),name=String(archive.attendee_name||'').trim();
  const date=new Date(archive.call_date);
  if(typeof body.transcript!=='string'||!body.transcript.trim()||body.transcript.length>200000)throw new Error('Transcript must be non-empty text, at most 200000 characters. Raw input remains archived.');
  if(!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(email)||email.length>254)throw new Error('Attendee email is missing or invalid. Raw input remains archived.');
  if(!name||name.length>255)throw new Error('Attendee name is missing or too long. Raw input remains archived.');
  if(typeof body.call_date!=='string'||!Number.isFinite(date.getTime()))throw new Error('Call date must be a valid ISO date or timestamp. Raw input remains archived.');
  if(body.call_id!=null&&(typeof body.call_id!=='string'||!body.call_id.trim()||body.call_id.length>200))throw new Error('Optional call_id must be text, 1–200 characters.');
  const canonical=body.call_id ? ['caller-id',body.call_id.trim()] : ['content',email,date.toISOString(),body.transcript.trim()];
  return {transcript_id:archive.id,transcript:archive.transcript,call_date:date.toISOString(),attendee_email:email,attendee_name:name,email_soql:soql(email),call_key:hash(JSON.stringify(canonical))};
}

const crypto=require('crypto');return [{json:checkCall($input.first().json,$('Receive transcript').first().json.body,s=>crypto.createHash('sha256').update(s).digest('hex'))}];

function selectRecord(call,leadRows,contactRows,opportunityRows) {
  const leads=leadRows.filter(r=>r.Id),contacts=contactRows.filter(r=>r.Id);
  let match={record_type:'unmatched',matched_record_id:'unmatched',owner_id:null,contact_id:null,match_reason:'No Lead or Contact matched the attendee email'};
  if(leads.length===1)match={record_type:'Lead',matched_record_id:leads[0].Id,owner_id:leads[0].OwnerId,contact_id:null,match_reason:'One exact-email Lead'};
  else if(leads.length>1)match.match_reason='Multiple Leads share this email; manual linking required';
  else if(contacts.length===1) {
    const c=contacts[0],opps=[...new Map(opportunityRows.map(r=>r.Opportunity).filter(o=>o?.Id).map(o=>[o.Id,o])).values()];
    match={record_type:'Contact',matched_record_id:c.Id,owner_id:c.OwnerId,contact_id:c.Id,match_reason:opps.length>1?'Contact matched; multiple open Opportunities, so no Opportunity guessed':'One exact-email Contact'};
    if(opps.length===1)match={record_type:'Opportunity',matched_record_id:opps[0].Id,owner_id:opps[0].OwnerId,contact_id:c.Id,match_reason:'One open Opportunity linked through the matched Contact'};
  } else if(contacts.length>1)match.match_reason='Multiple Contacts share this email; manual linking required';
  if(match.matched_record_id!=='unmatched'&&!/^[a-zA-Z0-9]{15}(?:[a-zA-Z0-9]{3})?$/.test(match.matched_record_id))throw new Error('Salesforce returned an invalid record ID');
  return {...call,...match};
}

const leads=$('Find Lead').all().map(i=>i.json);const contacts=$('Find Contact').isExecuted?$('Find Contact').all().map(i=>i.json):[];const opps=$('Find linked Opportunity').isExecuted?$('Find linked Opportunity').all().map(i=>i.json):[];return [{json:selectRecord($('Check call input').first().json,leads,contacts,opps)}];

function intelligence(call,result) {
  const a=result.output||result.text||result;
  if(!a||typeof a!=='object'||!a.summary||!Array.isArray(a.action_items)||!Array.isArray(a.objections)||!Array.isArray(a.next_steps)||!['none','low','medium','high'].includes(a.deal_risk_flag?.level)||!a.deal_risk_flag?.reason||!a.suggested_follow_up_email?.subject||!a.suggested_follow_up_email?.body)throw new Error('AI output is missing required structured fields; stopped before business writes.');
  return {transcript_id:call.transcript_id,call_key:call.call_key,matched_record_id:call.matched_record_id,record_type:call.record_type,summary:a.summary,action_items:a.action_items,objections:a.objections,next_steps:a.next_steps,deal_risk_flag:a.deal_risk_flag.level,risk_reason:a.deal_risk_flag.reason,suggested_follow_up_email:a.suggested_follow_up_email,status:'processing'};
}

return [{json:intelligence($('Select Salesforce record').first().json,$input.first().json)}];

function taskFields(call,row) {
  const date=String(call.call_date||'').slice(0,10);
  const actions=Array.isArray(row.action_items)?row.action_items:[];
  const validDates=actions.map(a=>String(a.due_date||'').trim())
    .filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d+'T00:00:00Z'))&&new Date(d+'T00:00:00Z').toISOString().slice(0,10)===d).sort();
  const due=validDates[0]||null,marker=' ['+row.call_key+']';
  const title=('Post-call: '+String(call.attendee_name||'Customer')+' — '+date).slice(0,255-marker.length);
  const fields={
    subject:title+marker,
    description:[
      'CALL SUMMARY\n'+row.summary,
      'CALL DETAILS\nDate: '+call.call_date+'\nAttendee: '+call.attendee_name+' <'+call.attendee_email+'>',
      'ACTION ITEMS\n'+(actions.map(x=>'- '+x.task+'\n  Owner: '+(x.owner||'Not specified')+'\n  Due: '+(x.due_date||'Not specified')).join('\n')||'None stated'),
      'OBJECTIONS\n'+((row.objections||[]).map(x=>'- '+x).join('\n')||'None stated'),
      'NEXT STEPS\n'+((row.next_steps||[]).map(x=>'- '+x).join('\n')||'None stated'),
      'DEAL RISK\n'+row.deal_risk_flag+' — '+row.risk_reason,
      'TASK DUE DATE\n'+(due?due+' (earliest stated action-item date; individual deadlines are listed above)':'Not set: no unambiguous YYYY-MM-DD deadline was extracted. See the action-item wording above.'),
      'REFERENCES\nMatch: '+call.match_reason+'\nCall key: '+row.call_key+'\nTranscript archive: '+row.transcript_id
    ].join('\n\n').slice(0,30000),
    priority:row.deal_risk_flag==='high'?'High':'Normal',
    activityDate:due
  };
  if(call.record_type==='Opportunity'){fields.whatId=call.matched_record_id;fields.whoId=call.contact_id;}
  else fields.whoId=call.matched_record_id;
  if(/^005[a-zA-Z0-9]{12}(?:[a-zA-Z0-9]{3})?$/.test(call.owner_id||''))fields.owner={__rl:true,mode:'id',value:call.owner_id};
  if(!fields.whoId)throw new Error('Matched call has no Lead or Contact ID; stopped before Task creation');
  return fields;
}

return [{json:taskFields($('Select Salesforce record').first().json,$('Use saved intelligence').first().json)}];

function slackText(s,max=3500) {return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').slice(0,max);}

function notification(call,row,slack,ownerEmail) {
  let slackId=slack?.ok&&/^[UW][A-Z0-9]+$/.test(slack.user?.id||'')?slack.user.id:null;
  if(slack&&!slack.ok&&slack.error!=='users_not_found')throw new Error('Slack owner lookup failed: '+String(slack.error||'unknown_error').slice(0,100));
  const unmatched=call.matched_record_id==='unmatched',fallback=unmatched||!slackId;
  let prefix=unmatched?'NEEDS MANUAL LINKING — no unique Salesforce match. Salesforce was NOT updated.':
    slackId?'<@'+slackId+'> Salesforce Task is logged.':'NEEDS OWNER MAPPING — Salesforce Task is logged; no Slack owner could be resolved.';
  return {channel:fallback?'<YOUR_SLACK_CHANNEL_ID>':'<YOUR_SLACK_CHANNEL_ID>',
    text:prefix+'\nAttendee: '+slackText(call.attendee_name,255)+'\nCall: '+slackText(call.call_date,100)+'\nSummary: '+slackText(row.summary,3200)+'\nRisk: '+row.deal_risk_flag+' — '+slackText(row.risk_reason,500)+'\nGmail draft is ready in the connected mailbox (not sent). Draft ID: '+slackText(row.gmail_draft_id,200)+'\n'+(unmatched?'Match: '+slackText(call.match_reason,300):'Salesforce record: '+call.record_type+' '+call.matched_record_id)+'\nCall key: '+row.call_key};
}

const row=$('Save Gmail draft ID').first().json.body[0];
if(!row?.gmail_draft_id)throw new Error("Draft ID was not saved; cannot claim draft ready");
const lookup=$('Find Slack owner').isExecuted?$('Find Slack owner').first().json:null;
return [{json:notification($('Select Salesforce record').first().json,row,lookup,null)}];
